// S-10 G4 (usted), G5 (placeholders) and G6 (glossary) — spec
// docs/superpowers/specs/2026-10-31-spanish-dashboard-design.md §5.2. The
// live checks freeze today's breaches in spanish-style-baseline.json
// (regenerated by scripts/generate-i18n-baseline.ts, never hand-edited to
// admit a new one) and fail only on a NEW breach; fixing one never needs a
// baseline edit.
import { describe, it, expect } from "vitest";
import {
  twinPairs, registerViolations, placeholderMismatches, glossaryViolations, GLOSSARY_RULES, TU_WORDS,
} from "./spanish-style";
import { parityViolations } from "./ratchet-scan";
import frozen from "./spanish-style-baseline.json";
import { m } from "@/lib/messages";

describe("twinPairs", () => {
  it("pairs x with x.es and x.en with x.es, and skips a .es with no English (mutation: drop the .en lookup → FAILS)", () => {
    const pairs = twinPairs({ "a": "A", "a.es": "Á", "b.en": "B", "b.es": "Bé", "c.es": "Cé" });
    expect(pairs.map((p) => p.key).sort()).toEqual(["a.es", "b.es"]);
  });
});

describe("G4 registerViolations — usted, never tú", () => {
  const cat = (es: string) => ({ "k": "English", "k.es": es });

  it.each([
    ["tus", "Tus preferencias"], ["ti", "Solo son para ti."], ["te", "Le escribimos y te contactamos."],
    ["inténtalo", "Recárguela e inténtalo de nuevo."], ["recárgala", "Recárgala, por favor."],
    ["verás", "Verás el tema."], ["agregaste", "Si agregaste la hora…"], ["has", "Aún no has elegido."],
    // S-10 review M-4.
    ["estás", "Ya estás dentro."], ["eres", "Ya eres el dueño."], ["podrás", "Podrás verlo mañana."],
    ["recibirás", "Recibirás un aviso."], ["puedas", "Cuando puedas, revisa."], ["tengas", "Si tengas dudas…"],
    ["quieras", "Lo que quieras."], ["hayas", "Cuando hayas terminado."], ["tuyo", "Es tuyo."],
  ])("flags %s (mutation: drop it from TU_WORDS → FAILS by name)", (_word, es) => {
    expect(registerViolations(cat(es))).toEqual(["k.es"]);
  });

  it.each([
    ["usted imperative", "Recárguela e inténtelo de nuevo."],
    ["third-person 'revisa'", "El sistema revisa cada cita."],
    ["'existe' (a suffix rule's false hit)", "Esta versión no existe."],
    ["'té' is not 'te'", "Un té para el equipo."],
    ["a {tu} placeholder", "Hola {tu}"],
    ["'eres' inside 'caracteres'", "Use 120 caracteres como máximo."],
    ["'eres' inside 'quieres' is still caught by 'quieres', not by 'eres': here none of it", "Mujeres y hombres."],
  ])("passes %s (mutation: match -iste as a suffix, or drop the letter boundaries → FAILS)", (_why, es) => {
    expect(registerViolations(cat(es))).toEqual([]);
  });

  it("the list holds only forms that cannot be third person: no 'revisa', 'vuelve', 'elige', 'responde' (mutation: add one → FAILS)", () => {
    for (const w of ["revisa", "vuelve", "elige", "responde", "recarga"]) expect(TU_WORDS, w).not.toContain(w);
  });
});

describe("G5 placeholderMismatches", () => {
  it("flags a twin that drops or renames a placeholder (mutation: compare counts only → FAILS on the rename)", () => {
    expect(placeholderMismatches({ "a": "{count} calls", "a.es": "llamadas", "b": "{name}", "b.es": "{nombre}", "c": "{x} y", "c.es": "{x} y" }))
      .toEqual(["a.es", "b.es"]);
  });

  it("is zero over the whole catalogue, with no frozen list (mutation: drop {count} from any .es → FAILS naming it)", () => {
    expect(placeholderMismatches(m)).toEqual([]);
  });
});

describe("G6 glossaryViolations — the glossary's 'Never' column", () => {
  it.each(GLOSSARY_RULES.map((r) => [r.id, r] as const))("rule %s fires on its banned word and only when the English holds its term", (_id, r) => {
    const samples: Record<string, [string, string]> = {
      settings: ["Settings", "Configuración"], delete: ["Delete", "Eliminar"], book: ["Booked online", "Reservada en línea"],
      "try-again": ["Try again", "Reintentar"], estimate: ["Estimate", "Presupuesto"], add: ["Add", "Añadir"],
      email: ["Email", "E-mail"], text: ["Text", "SMS"], lead: ["Lead", "Prospecto"], staff: ["Staff", "Personal"],
      owner: ["Owner", "Propietario"], upload: ["Upload", "Cargar"],
      dashboard: ["Back to dashboard", "Volver al tablero"], deal: ["Open deals", "Tratos abiertos"],
      appointment: ["Appointment", "Reserva"], reschedule: ["Reschedule", "Reprogramar"],
      answered: ["Calls answered", "Llamadas contestadas"], trade: ["Business trade", "Oficio del negocio"],
      "to-do": ["To do", "Tareas"],
    };
    const [en, es] = samples[r.id]!;
    expect(glossaryViolations({ "k": en, "k.es": es }, [r])).toEqual([`k.es|${r.id}`]);
    expect(glossaryViolations({ "k": "Unrelated words", "k.es": es }, [r])).toEqual([]);
  });

  it("every rule has a sample above (mutation: add a rule without one → FAILS)", () => {
    expect(GLOSSARY_RULES.map((r) => r.id).sort()).toEqual([
      "add", "answered", "appointment", "book", "dashboard", "deal", "delete", "email", "estimate", "lead", "owner",
      "reschedule", "settings", "staff", "text", "to-do", "trade", "try-again", "upload",
    ]);
  });

  it("the S-10 review's rules have no breach today, so they are hard: none of them is on the frozen list (mutation: freeze one → FAILS)", () => {
    const hard = ["dashboard", "deal", "reschedule", "answered", "trade", "to-do"];
    expect(frozen.glossary.filter((e) => hard.includes(e.split("|")[1]!))).toEqual([]);
  });

  it("ignores placeholders, so {email} is not the word 'email' (mutation: test the raw strings → FAILS)", () => {
    expect(glossaryViolations({ "k": "Sent to {email}", "k.es": "Enviado a {email}" })).toEqual([]);
  });

  it("'agency staff' is not the Staff role (mutation: drop the lookbehind → FAILS)", () => {
    expect(glossaryViolations({ "k": "Agency staff stay in English.", "k.es": "El personal de la agencia sigue en inglés." })).toEqual([]);
  });
});

describe("G4 and G6, live", () => {
  it("no NEW tú string (mutation: put 'Inténtalo de nuevo.' in any .es → FAILS naming the key)", () => {
    const v = parityViolations(registerViolations(m), frozen.register);
    expect(v, `write these in usted: ${v.join(", ")}`).toEqual([]);
  });

  it("no NEW glossary breach (mutation: 'Eliminar' as the twin of an English 'Delete' → FAILS naming key|rule)", () => {
    const v = parityViolations(glossaryViolations(m), frozen.glossary);
    expect(v, `use the glossary word (spec §4.3) for: ${v.join(", ")}`).toEqual([]);
  });
});
